import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";
import { HttpMetricsProvider } from "../src/providers/http.ts";
import type { ProviderError } from "../src/providers/port.ts";
import { PROVIDERS } from "../src/providers/adapters.ts";
import { startSimulator } from "./sim.ts";

let sim: Awaited<ReturnType<typeof startSimulator>>;
const NOW = new Date("2026-06-01T12:00:00.000Z");
const WINDOW = { account: "acc_1", token: "tok-1", since: "2026-05-01T00:00:00.000Z", until: "2026-05-31T23:59:59.999Z", cursor: null };

beforeAll(async () => {
  sim = await startSimulator();
});
afterAll(() => sim.close());
beforeEach(() => {
  sim.state.reset();
  sim.state.now = NOW;
});

const provider = (network: (typeof PROVIDERS)[number], extra: { timeoutMs?: number } = {}) =>
  new HttpMetricsProvider({ baseUrl: sim.baseUrl, network, timeoutMs: extra.timeoutMs ?? 500, now: () => NOW });

const errorOf = async (promise: Promise<unknown>) => (await promise.then(() => null, (e: ProviderError) => e)) as ProviderError;

describe("cliente HTTP do provedor", () => {
  it.each(PROVIDERS)("%s: busca por janela e entrega os posts no formato único", async (network) => {
    sim.state.setPosts(network, "acc_1", [
      { id: "a", publishedAt: "2026-05-10T10:00:00.000Z", views: 100, likes: 5, comments: 2, shares: 1 },
      { id: "b", publishedAt: "2026-04-10T10:00:00.000Z", views: 999 }, // fora da janela
    ]);
    const result = await provider(network).fetchPosts(WINDOW);
    expect(result.nextCursor).toBeNull();
    expect(result.invalid).toBe(0);
    expect(result.items).toHaveLength(1);
    expect(result.items[0]).toMatchObject({ postId: "a", publishedAt: "2026-05-10T10:00:00.000Z", asOf: NOW.toISOString(), views: 100 });
  });

  it("manda o token no cabeçalho e a janela, a conta e o cursor na URL", async () => {
    await provider("instagram").fetchPosts({ ...WINDOW, account: "conta com espaço", cursor: "3" });
    expect(sim.state.requests[0]).toMatchObject({
      network: "instagram",
      account: "conta com espaço",
      authorization: "Bearer tok-1",
      since: WINDOW.since,
      until: WINDOW.until,
      cursor: "3",
    });
  });

  it("pagina com cursor", async () => {
    sim.state.pageSize = 2;
    sim.state.setPosts("x", "acc_1", ["a", "b", "c"].map((id, i) => ({ id, publishedAt: `2026-05-1${i}T10:00:00.000Z`, views: i + 1 })));
    const first = await provider("x").fetchPosts(WINDOW);
    expect(first.items).toHaveLength(2);
    expect(first.nextCursor).toBe("2");
    const second = await provider("x").fetchPosts({ ...WINDOW, cursor: first.nextCursor });
    expect(second.items).toHaveLength(1);
    expect(second.nextCursor).toBeNull();
  });

  it("itens inválidos são contados em vez de virarem número", async () => {
    sim.state.setPosts("instagram", "acc_1", [{ id: "a", publishedAt: "2026-05-10T10:00:00.000Z", views: 100 }]);
    sim.state.corruptItems = 2;
    const result = await provider("instagram").fetchPosts(WINDOW);
    expect(result.items).toHaveLength(1);
    expect(result.invalid).toBe(2);
  });

  describe("429", () => {
    it("Retry-After em segundos vira milissegundos", async () => {
      sim.state.behaviors = [{ status: 429, retryAfter: "7" }];
      const error = await errorOf(provider("x").fetchPosts(WINDOW));
      expect(error).toMatchObject({ kind: "rate_limited", status: 429, retryAfterMs: 7000 });
    });

    it("Retry-After em data HTTP vira a diferença para agora", async () => {
      sim.state.behaviors = [{ status: 429, retryAfter: "Mon, 01 Jun 2026 12:00:10 GMT" }];
      const error = await errorOf(provider("x").fetchPosts(WINDOW));
      expect(error).toMatchObject({ kind: "rate_limited", retryAfterMs: 10_000 });
    });

    it("sem Retry-After, ou com ele inválido, é null", async () => {
      sim.state.behaviors = [{ status: 429 }, { status: 429, retryAfter: "daqui a pouco" }];
      expect(await errorOf(provider("x").fetchPosts(WINDOW))).toMatchObject({ kind: "rate_limited", retryAfterMs: null });
      expect(await errorOf(provider("x").fetchPosts(WINDOW))).toMatchObject({ kind: "rate_limited", retryAfterMs: null });
    });
  });

  it.each([
    [500, "server"],
    [502, "server"],
    [503, "server"],
    [408, "timeout"],
    [400, "client"],
    [401, "client"],
    [403, "client"],
    [404, "client"],
  ])("resposta %i é falha do tipo %s", async (status, kind) => {
    sim.state.behaviors = [{ status }];
    expect(await errorOf(provider("x").fetchPosts(WINDOW))).toMatchObject({ kind, status });
  });

  it("provedor que não responde a tempo é timeout", async () => {
    sim.state.behaviors = ["timeout"];
    sim.state.timeoutDelayMs = 600;
    expect(await errorOf(provider("x", { timeoutMs: 100 }).fetchPosts(WINDOW))).toMatchObject({ kind: "timeout" });
  });

  it("a URL base com barras no fim funciona do mesmo jeito (sem //v1)", async () => {
    sim.state.setPosts("x", "acc_1", [{ id: "a", publishedAt: "2026-05-10T10:00:00.000Z", views: 1 }]);
    for (const suffix of ["/", "///"]) {
      const withSlashes = new HttpMetricsProvider({ baseUrl: sim.baseUrl + suffix, network: "x", timeoutMs: 500, now: () => NOW });
      expect((await withSlashes.fetchPosts(WINDOW)).items).toHaveLength(1);
    }
  });

  it.each([
    ["TimeoutError", "TimeoutError"],
    ["AbortError", "AbortError"],
  ])("fetch que falha com %s é timeout; qualquer outro erro é rede", async (_label, name) => {
    const failing = (error: Error) => new HttpMetricsProvider({ baseUrl: sim.baseUrl, network: "x", fetch: (async () => { throw error; }) as typeof fetch });
    expect(await errorOf(failing(new DOMException("tempo", name)).fetchPosts(WINDOW))).toMatchObject({ kind: "timeout" });
    expect(await errorOf(failing(new TypeError("fetch failed")).fetchPosts(WINDOW))).toMatchObject({ kind: "network" });
  });

  it("resposta sem next_cursor é a última página", async () => {
    sim.state.behaviors = [{ status: 200, body: '{"data":[]}' }];
    expect(await provider("x").fetchPosts(WINDOW)).toEqual({ items: [], invalid: 0, nextCursor: null });
  });

  it("sem relógio injetado, o Retry-After em data HTTP usa o relógio real", async () => {
    sim.state.behaviors = [{ status: 429, retryAfter: new Date(Date.now() + 10_000).toUTCString() }];
    const realClock = new HttpMetricsProvider({ baseUrl: sim.baseUrl, network: "x", timeoutMs: 500 });
    const error = await errorOf(realClock.fetchPosts(WINDOW));
    expect(error.retryAfterMs).toBeGreaterThan(7_000);
    expect(error.retryAfterMs).toBeLessThanOrEqual(10_000);
  });

  it("provedor fora do ar é erro de rede", async () => {
    const down = new HttpMetricsProvider({ baseUrl: "http://127.0.0.1:1", network: "x", timeoutMs: 300 });
    expect(await errorOf(down.fetchPosts(WINDOW))).toMatchObject({ kind: "network" });
  });

  it.each([
    ["JSON malformado", "{nope"],
    ["corpo sem a lista data", '{"outro":1}'],
    ["data que não é lista", '{"data":"texto"}'],
    ["corpo nulo", "null"],
  ])("%s é payload inválido", async (_name, body) => {
    sim.state.behaviors = [{ status: 200, body }];
    expect(await errorOf(provider("x").fetchPosts(WINDOW))).toMatchObject({ kind: "invalid_payload" });
  });

  it("next_cursor que não é texto é payload inválido", async () => {
    sim.state.behaviors = [{ status: 200, body: '{"data":[],"next_cursor":42}' }];
    expect(await errorOf(provider("x").fetchPosts(WINDOW))).toMatchObject({ kind: "invalid_payload" });
  });
});

test/retry.test.ts.source:
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { decide, type Failure, type Policy } from "../src/domain/retry.ts";
import { parseRetryAfter } from "../src/domain/retry-after.ts";

const policy: Policy = { maxAttempts: 4, baseDelayMs: 200, maxBackoffMs: 5000, maxRetryAfterMs: 30_000 };
const transient = (kind: Failure["kind"]): Failure => ({ kind });

describe("política de retry", () => {
  it.each(["timeout", "network", "server"] as const)("falha transitória (%s) tenta de novo com espera exponencial: 200, 400, 800 ms", (kind) => {
    expect(decide(transient(kind), 1, policy)).toEqual({ action: "retry", waitMs: 200 });
    expect(decide(transient(kind), 2, policy)).toEqual({ action: "retry", waitMs: 400 });
    expect(decide(transient(kind), 3, policy)).toEqual({ action: "retry", waitMs: 800 });
  });

  it("depois da última tentativa permitida, desiste: não há laço infinito", () => {
    expect(decide(transient("timeout"), 4, policy)).toEqual({ action: "fail" });
    expect(decide(transient("server"), 5, policy)).toEqual({ action: "fail" });
  });

  it("a espera exponencial tem teto", () => {
    const wide = { ...policy, maxAttempts: 20 };
    expect(decide(transient("timeout"), 6, wide)).toEqual({ action: "retry", waitMs: 5000 });
    expect(decide(transient("timeout"), 15, wide)).toEqual({ action: "retry", waitMs: 5000 });
  });

  it.each(["client", "invalid_payload"] as const)("%s não adianta repetir: falha na hora", (kind) => {
    expect(decide({ kind }, 1, policy)).toEqual({ action: "fail" });
  });

  describe("429 com Retry-After", () => {
    const limited = (retryAfterMs: number | null): Failure => ({ kind: "rate_limited", retryAfterMs });

    it("espera exatamente o que o provedor mandou (não o backoff)", () => {
      expect(decide(limited(7000), 1, policy)).toEqual({ action: "retry", waitMs: 7000 });
      expect(decide(limited(1500), 3, policy)).toEqual({ action: "retry", waitMs: 1500 });
    });

    it("no teto exato ainda espera; um milissegundo acima, adia sem esperar", () => {
      expect(decide(limited(30_000), 1, policy)).toEqual({ action: "retry", waitMs: 30_000 });
      expect(decide(limited(30_001), 1, policy)).toEqual({ action: "defer", retryAfterMs: 30_001 });
    });

    it("Retry-After 0 tenta de novo na hora, mas ainda gasta uma tentativa", () => {
      expect(decide(limited(0), 1, policy)).toEqual({ action: "retry", waitMs: 0 });
      expect(decide(limited(0), 4, policy)).toEqual({ action: "defer", retryAfterMs: 0 });
    });

    it("esgotadas as tentativas, adia para quando o provedor mandou em vez de falhar", () => {
      expect(decide(limited(7000), 4, policy)).toEqual({ action: "defer", retryAfterMs: 7000 });
    });

    it("sem Retry-After usa o backoff, e esgotadas as tentativas falha", () => {
      expect(decide(limited(null), 1, policy)).toEqual({ action: "retry", waitMs: 200 });
      expect(decide(limited(null), 2, policy)).toEqual({ action: "retry", waitMs: 400 });
      expect(decide(limited(null), 4, policy)).toEqual({ action: "fail" });
    });
  });

  it("só o 429 usa o Retry-After: o mesmo valor numa falha de servidor é ignorado e vale o backoff", () => {
    expect(decide({ kind: "server", retryAfterMs: 25_000 }, 1, policy)).toEqual({ action: "retry", waitMs: 200 });
    expect(decide({ kind: "timeout", retryAfterMs: 25_000 }, 2, policy)).toEqual({ action: "retry", waitMs: 400 });
    expect(decide({ kind: "server", retryAfterMs: 999_999 }, 4, policy)).toEqual({ action: "fail" });
  });

  it("propriedade: a espera nunca passa do maior entre o teto do backoff e o teto do Retry-After, e as tentativas têm limite", () => {
    fc.assert(
      fc.property(
        fc.constantFrom<Failure["kind"]>("timeout", "network", "server", "rate_limited", "client", "invalid_payload"),
        fc.option(fc.integer({ min: 0, max: 120_000 }), { nil: null }),
        fc.integer({ min: 1, max: 10 }),
        (kind, retryAfterMs, attempt) => {
          const result = decide({ kind, retryAfterMs }, attempt, policy);
          if (attempt >= policy.maxAttempts) expect(result.action).not.toBe("retry");
          if (result.action === "retry") expect(result.waitMs).toBeLessThanOrEqual(Math.max(policy.maxBackoffMs, policy.maxRetryAfterMs));
          if (result.action === "defer") expect(result.retryAfterMs).toBe(retryAfterMs);
        },
      ),
    );
  });
});

describe("Retry-After: segundos ou data HTTP", () => {
  const now = new Date("2026-06-01T12:00:00.000Z");

  it.each([
    ["7", 7000],
    ["0", 0],
    ["120", 120_000],
    [" 5 ", 5000],
  ])("segundos %j viram %i ms", (value, ms) => {
    expect(parseRetryAfter(value, now)).toBe(ms);
  });

  it("data HTTP vira a diferença para agora", () => {
    expect(parseRetryAfter("Mon, 01 Jun 2026 12:00:10 GMT", now)).toBe(10_000);
  });

  it("data HTTP já passada vira 0, não um tempo negativo", () => {
    expect(parseRetryAfter("Mon, 01 Jun 2026 11:59:00 GMT", now)).toBe(0);
  });

  it.each(["", "abc", "-5", "1.5", "5s", "NaN", "Infinity", "99999999999999999999"])("valor inválido %j é ausente (null), não um número", (value) => {
    expect(parseRetryAfter(value, now)).toBeNull();
  });

  it.each([
    "xx Mon, 01 Jun 2026 12:00:10 GMT",
    "Mon, 01 Jun 2026 12:00:10 GMT extra",
    "Mon, 01 Jun 2026 12:00:10",
    "Mon, 01 Jun 2026 12:00:10 PST",
  ])("data HTTP com lixo ao redor ou fora do formato (%j) é inválida", (value) => {
    expect(parseRetryAfter(value, now)).toBeNull();
  });

  it("ausente é null", () => {
    expect(parseRetryAfter(null, now)).toBeNull();
    expect(parseRetryAfter(undefined, now)).toBeNull();
  });
});

test/body-read.test.ts.source:
import { describe, expect, it } from "vitest";
import { createApp } from "../src/app.ts";
import { openDatabase } from "../src/db.ts";
import { HttpMetricsProvider } from "../src/providers/http.ts";
import type { ProviderError } from "../src/providers/port.ts";
import { DEFAULT_POLICY, ALL, START } from "./helpers.ts";
import { FakeClock } from "./fakes.ts";

const WINDOW = { account: "acc_1", token: "tok-1", since: ALL.since, until: ALL.until, cursor: null };

/** Resposta 200 cujos cabeçalhos chegam e cujo corpo é interrompido no meio por `error`. */
const brokenBody = (error: unknown) => new Response(new ReadableStream({ start: (controller) => controller.error(error) }), { status: 200, headers: { "content-type": "application/json" } });
const okBody = () => new Response('{"data":[],"next_cursor":null}', { status: 200, headers: { "content-type": "application/json" } });

const providerWith = (responses: Array<() => Response>) => {
  const queue = [...responses];
  return new HttpMetricsProvider({ baseUrl: "http://provedor.invalido", network: "x", fetch: (async () => queue.shift()!()) as typeof fetch });
};
const errorOf = async (promise: Promise<unknown>) => (await promise.then(() => null, (e: ProviderError) => e)) as ProviderError;

describe("falha ao ler o corpo é falha de transporte, não JSON inválido", () => {
  it("corpo interrompido por TimeoutError ou AbortError é timeout", async () => {
    expect(await errorOf(providerWith([() => brokenBody(new DOMException("tempo esgotado", "TimeoutError"))]).fetchPosts(WINDOW))).toMatchObject({ kind: "timeout" });
    expect(await errorOf(providerWith([() => brokenBody(new DOMException("abortado", "AbortError"))]).fetchPosts(WINDOW))).toMatchObject({ kind: "timeout" });
  });

  it("corpo interrompido por erro de conexão é network", async () => {
    expect(await errorOf(providerWith([() => brokenBody(new TypeError("terminated"))]).fetchPosts(WINDOW))).toMatchObject({ kind: "network" });
  });

  it("JSON sintaticamente inválido continua sendo payload inválido, e a mensagem diz que o corpo chegou", async () => {
    const error = await errorOf(providerWith([() => new Response("{nope", { status: 200 })]).fetchPosts(WINDOW));
    expect(error).toMatchObject({ kind: "invalid_payload" });
  });

  it("corpo vazio é payload inválido, não timeout", async () => {
    expect(await errorOf(providerWith([() => new Response("", { status: 200 })]).fetchPosts(WINDOW))).toMatchObject({ kind: "invalid_payload" });
  });
});

describe("a sincronização repete a página quando o corpo da primeira resposta se perde", () => {
  function appWith(provider: HttpMetricsProvider) {
    const clock = new FakeClock(START);
    const app = createApp({ db: openDatabase(":memory:"), providerFor: () => provider, now: clock.now, sleep: clock.sleep, policy: DEFAULT_POLICY, maxPages: 50 });
    const call = async (method: string, path: string, body?: unknown) => {
      const res = await app.request(path, { method, headers: { "content-type": "application/json" }, body: body === undefined ? undefined : JSON.stringify(body) });
      return { status: res.status, body: (await res.json()) as any };
    };
    return { call, clock };
  }

  it("200 com corpo interrompido e depois uma resposta boa: tenta de novo e termina succeeded", async () => {
    const { call, clock } = appWith(providerWith([() => brokenBody(new DOMException("tempo esgotado", "TimeoutError")), okBody]));
    const id = (await call("POST", "/connections", { provider: "x", account_id: "acc_1", token: "t" })).body.id as string;
    const run = await call("POST", `/connections/${id}/sync`, ALL);
    expect(run.status).toBe(200);
    expect(run.body).toMatchObject({ status: "succeeded", attempts: 2, waits_ms: [200] });
    expect(clock.waits).toEqual([200]);
  });

  it("JSON inválido continua terminal: uma tentativa só", async () => {
    const { call } = appWith(providerWith([() => new Response("{nope", { status: 200 }), okBody]));
    const id = (await call("POST", "/connections", { provider: "x", account_id: "acc_1", token: "t" })).body.id as string;
    const run = await call("POST", `/connections/${id}/sync`, ALL);
    expect(run.body).toMatchObject({ status: "failed", attempts: 1 });
  });
});

test/adapters.test.ts.source:
import { describe, expect, it } from "vitest";
import { normalizeItem, PROVIDERS } from "../src/providers/adapters.ts";

describe("cada rede fala do seu jeito; o resto do sistema vê um formato só", () => {
  it("Instagram", () => {
    expect(
      normalizeItem("instagram", { id: "ig_1", timestamp: "2026-05-30T10:00:00Z", snapshot_at: "2026-06-01T12:00:00Z", plays: 1200, like_count: 90, comments_count: 7, shares: 3 }),
    ).toEqual({ postId: "ig_1", publishedAt: "2026-05-30T10:00:00.000Z", asOf: "2026-06-01T12:00:00.000Z", views: 1200, likes: 90, comments: 7, shares: 3 });
  });

  it("TikTok (datas em segundos desde 1970)", () => {
    expect(
      normalizeItem("tiktok", { video_id: "tt_1", create_time: 1_780_000_000, snapshot_time: 1_780_086_400, play_count: 5000, digg_count: 400, comment_count: 20, share_count: 11 }),
    ).toEqual({ postId: "tt_1", publishedAt: "2026-05-28T20:26:40.000Z", asOf: "2026-05-29T20:26:40.000Z", views: 5000, likes: 400, comments: 20, shares: 11 });
  });

  it("YouTube (contadores como texto, sem compartilhamentos)", () => {
    expect(
      normalizeItem("youtube", { videoId: "yt_1", publishedAt: "2026-05-30T10:00:00Z", retrievedAt: "2026-06-01T12:00:00Z", viewCount: "98000", likeCount: "3100", commentCount: "250" }),
    ).toEqual({ postId: "yt_1", publishedAt: "2026-05-30T10:00:00.000Z", asOf: "2026-06-01T12:00:00.000Z", views: 98000, likes: 3100, comments: 250, shares: 0 });
  });

  it("X (impressões contam como views)", () => {
    expect(
      normalizeItem("x", { tweet_id: "x_1", created_at: "2026-05-30T10:00:00Z", as_of: "2026-06-01T12:00:00Z", impression_count: 777, like_count: 30, reply_count: 4, retweet_count: 9 }),
    ).toEqual({ postId: "x_1", publishedAt: "2026-05-30T10:00:00.000Z", asOf: "2026-06-01T12:00:00.000Z", views: 777, likes: 30, comments: 4, shares: 9 });
  });

  it("as quatro redes estão cobertas", () => {
    expect([...PROVIDERS].sort()).toEqual(["instagram", "tiktok", "x", "youtube"]);
  });

  it.each([
    ["sem id", "instagram", { timestamp: "2026-05-30T10:00:00Z", snapshot_at: "2026-06-01T12:00:00Z", plays: 1 }],
    ["id vazio", "instagram", { id: "  ", timestamp: "2026-05-30T10:00:00Z", snapshot_at: "2026-06-01T12:00:00Z", plays: 1 }],
    ["sem views", "instagram", { id: "a", timestamp: "2026-05-30T10:00:00Z", snapshot_at: "2026-06-01T12:00:00Z" }],
    ["views negativas", "instagram", { id: "a", timestamp: "2026-05-30T10:00:00Z", snapshot_at: "2026-06-01T12:00:00Z", plays: -1 }],
    ["views fracionárias", "instagram", { id: "a", timestamp: "2026-05-30T10:00:00Z", snapshot_at: "2026-06-01T12:00:00Z", plays: 1.5 }],
    ["views em texto não numérico", "youtube", { videoId: "a", publishedAt: "2026-05-30T10:00:00Z", retrievedAt: "2026-06-01T12:00:00Z", viewCount: "muitas" }],
    ["data de publicação impossível", "instagram", { id: "a", timestamp: "2026-02-30T10:00:00Z", snapshot_at: "2026-06-01T12:00:00Z", plays: 1 }],
    ["data do snapshot ausente", "x", { tweet_id: "a", created_at: "2026-05-30T10:00:00Z", impression_count: 1 }],
    ["época fracionária", "tiktok", { video_id: "a", create_time: 1.5, snapshot_time: 1_780_086_400, play_count: 1 }],
    ["item que não é objeto", "x", "texto"],
    ["item nulo", "x", null],
  ])("item inválido (%s) vira null, não um número inventado", (_name, provider, raw) => {
    expect(normalizeItem(provider as "x", raw)).toBeNull();
  });

  it.each([
    ["texto vazio", ""],
    ["só espaço", " "],
    ["dígitos seguidos de letras", "12abc"],
    ["letras seguidas de dígitos", "abc12"],
    ["dois números", "1 2"],
    ["notação científica", "1e3"],
    ["hexadecimal", "0x10"],
    ["negativo em texto", "-5"],
    ["decimal em texto", "1.5"],
  ])("contador em texto inválido (%s: %j) invalida o item em vez de virar 0 ou outro número", (_name, value) => {
    expect(normalizeItem("youtube", { videoId: "a", publishedAt: "2026-05-30T10:00:00Z", retrievedAt: "2026-06-01T12:00:00Z", viewCount: value })).toBeNull();
    expect(normalizeItem("youtube", { videoId: "a", publishedAt: "2026-05-30T10:00:00Z", retrievedAt: "2026-06-01T12:00:00Z", viewCount: "10", likeCount: value })).toBeNull();
  });

  it("contador em texto de dígitos válido, inclusive com zeros à esquerda e zero, vale", () => {
    const base = { videoId: "a", publishedAt: "2026-05-30T10:00:00Z", retrievedAt: "2026-06-01T12:00:00Z" };
    expect(normalizeItem("youtube", { ...base, viewCount: "0" })).toMatchObject({ views: 0 });
    expect(normalizeItem("youtube", { ...base, viewCount: "007" })).toMatchObject({ views: 7 });
  });

  it("TikTok: a época 0 (1970) é uma data válida; negativa, em texto ou fracionária não", () => {
    const item = (create_time: unknown) => ({ video_id: "a", create_time, snapshot_time: 1_780_086_400, play_count: 1 });
    expect(normalizeItem("tiktok", item(0))).toMatchObject({ publishedAt: "1970-01-01T00:00:00.000Z" });
    expect(normalizeItem("tiktok", item(-1))).toBeNull();
    expect(normalizeItem("tiktok", item("1780000000"))).toBeNull();
    expect(normalizeItem("tiktok", item(1.5))).toBeNull();
    expect(normalizeItem("tiktok", item(Number.MAX_SAFE_INTEGER))).toBeNull();
  });

  it("item que é uma lista também é inválido", () => {
    expect(normalizeItem("x", [])).toBeNull();
    expect(normalizeItem("x", [{ tweet_id: "a" }])).toBeNull();
  });

  it.each([
    ["comentários", { comments_count: "x" }],
    ["compartilhamentos", { shares: -1 }],
    ["curtidas", { like_count: 1.5 }],
  ])("%s inválidos invalidam o item, cada um por si", (_name, extra) => {
    expect(normalizeItem("instagram", { id: "a", timestamp: "2026-05-30T10:00:00Z", snapshot_at: "2026-06-01T12:00:00Z", plays: 5, ...extra })).toBeNull();
  });

  it("contador opcional ausente vale 0, mas presente e inválido invalida o item", () => {
    expect(normalizeItem("instagram", { id: "a", timestamp: "2026-05-30T10:00:00Z", snapshot_at: "2026-06-01T12:00:00Z", plays: 5 })).toMatchObject({ likes: 0, comments: 0, shares: 0 });
    expect(normalizeItem("instagram", { id: "a", timestamp: "2026-05-30T10:00:00Z", snapshot_at: "2026-06-01T12:00:00Z", plays: 5, like_count: -3 })).toBeNull();
  });
});
